local PouringConeMaker = {}
local PRODUCTS = {
    iron_pouringcone = { name = "Železni lijak za vlivanje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni lijak za vlivanje za livarje." },
    bronze_pouringcone = { name = "Bronast lijak za vlivanje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast lijak za vlivanje za livarje." },
    silver_pouringcone = { name = "Srebrn lijak za vlivanje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn lijak za vlivanje za livarje." },
    gilded_pouringcone = { name = "Pozlačen lijak za vlivanje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen lijak za vlivanje za livarje." },
    jewel_set_pouringcone = { name = "Draguljast lijak za vlivanje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast lijak za vlivanje za livarje." },
    royal_sovereign_pouringcone = { name = "Kraljevski suveren lijak za vlivanje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren lijak za vlivanje z biseri za krono." },
}
local BUILDINGS = {
    pouringcone_workshop = { name = "Pouringcone delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    pouringcone_house = { name = "Pouringcone hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_pouringcone_atelier = { name = "Mojstrski pouringcone atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_pouringcone_palace = { name = "Suverena pouringcone palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
PouringConeMaker.ironStock=14; PouringConeMaker.bronzeStock=12; PouringConeMaker.woodStock=14; PouringConeMaker.leatherStock=8; PouringConeMaker.silverStock=8; PouringConeMaker.goldStock=6; PouringConeMaker.jewelStock=4; PouringConeMaker.pearlStock=4
PouringConeMaker.productStock = {}; PouringConeMaker.buildings = {}; PouringConeMaker.maker = nil; PouringConeMaker.activeMaking = {}; PouringConeMaker.totalProducts = 0; PouringConeMaker.dayTimer = 0
function PouringConeMaker.init() PouringConeMaker.ironStock=14; PouringConeMaker.bronzeStock=12; PouringConeMaker.woodStock=14; PouringConeMaker.leatherStock=8; PouringConeMaker.silverStock=8; PouringConeMaker.goldStock=6; PouringConeMaker.jewelStock=4; PouringConeMaker.pearlStock=4; PouringConeMaker.productStock={}; PouringConeMaker.buildings={}; PouringConeMaker.maker=nil; PouringConeMaker.activeMaking={}; PouringConeMaker.totalProducts=0; PouringConeMaker.dayTimer=0; print("[PouringConeMaker] Royal Pouring Cone Maker System initialized (6 products, 4 buildings)") end
function PouringConeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PouringConeMaker.maker={name=n or ("Lijakar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lijakar najet: %s (spretnost: %d)",PouringConeMaker.maker.name,s),"success") end; return true end
function PouringConeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PouringConeMaker.build(id) local ok,e=PouringConeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PouringConeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PouringConeMaker.getQualityBonus() local b=0; for _,bd in ipairs(PouringConeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PouringConeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PouringConeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PouringConeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PouringConeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PouringConeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PouringConeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PouringConeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PouringConeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PouringConeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PouringConeMaker.buildings==0 then return false,"Potrebna lijakna delavnica" end; if not PouringConeMaker.maker then return false,"Potreben lijakar" end; return true end
function PouringConeMaker.make(pt,qty) qty=qty or 1; local ok,e=PouringConeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PouringConeMaker.ironStock=PouringConeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PouringConeMaker.bronzeStock=PouringConeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PouringConeMaker.woodStock=PouringConeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PouringConeMaker.leatherStock=PouringConeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PouringConeMaker.silverStock=PouringConeMaker.silverStock-d.silverCost*qty end; if d.goldCost then PouringConeMaker.goldStock=PouringConeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PouringConeMaker.jewelStock=PouringConeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PouringConeMaker.pearlStock=PouringConeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PouringConeMaker.maker then t=math.max(1,t-math.floor(PouringConeMaker.maker.skill/13)) end; table.insert(PouringConeMaker.activeMaking,{id="pouringcone_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PouringConeMaker.completeMaking(m) local q=1.0+(PouringConeMaker.getQualityBonus()/100); if PouringConeMaker.maker then q=q+(PouringConeMaker.maker.skill/140) end; q=math.min(2.5,q); PouringConeMaker.productStock[m.productType]=(PouringConeMaker.productStock[m.productType] or 0)+m.quantity; PouringConeMaker.totalProducts=PouringConeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PouringConeMaker.maker then PouringConeMaker.maker.itemsMade=PouringConeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PouringConeMaker.maker.skill=math.min(100,PouringConeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lijak izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pouringcone.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PouringConeMaker.update(dt) if not _G.state then return end; PouringConeMaker.dayTimer=PouringConeMaker.dayTimer+dt; if PouringConeMaker.dayTimer>=30 then PouringConeMaker.dayTimer=0; for i=#PouringConeMaker.activeMaking,1,-1 do local m=PouringConeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PouringConeMaker.completeMaking(m); table.remove(PouringConeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PouringConeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PouringConeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PouringConeMaker.getStats() return {ironStock=PouringConeMaker.ironStock,bronzeStock=PouringConeMaker.bronzeStock,woodStock=PouringConeMaker.woodStock,leatherStock=PouringConeMaker.leatherStock,silverStock=PouringConeMaker.silverStock,goldStock=PouringConeMaker.goldStock,jewelStock=PouringConeMaker.jewelStock,pearlStock=PouringConeMaker.pearlStock,productStock=PouringConeMaker.productStock,numBuildings=#PouringConeMaker.buildings,hasMaker=PouringConeMaker.maker~=nil,makerName=PouringConeMaker.maker and PouringConeMaker.maker.name or "—",makerSkill=PouringConeMaker.maker and PouringConeMaker.maker.skill or 0,activeMaking=#PouringConeMaker.activeMaking,totalProducts=PouringConeMaker.totalProducts} end
return PouringConeMaker
